    desc: 'Read a variable by path, for example {{bbsVar::relationships.Alice.affinity}}. Requires the newer macro engine.',
  },
] as const;

async function copyDataMacro(token: string) {
  try {
    await navigator.clipboard.writeText(token);
    toast(`Copied ${token}`, 'success');
  } catch {
    toast('Copy failed, please select macro text manually', 'error');
  }
}

function exportPublicApiDocument() {
  const anchor = document.createElement('a');
  anchor.href = versionedAssetUrl('../PUBLIC_API.md', import.meta.url);
  anchor.download = 'ST-BaiBai-Book-PUBLIC_API.md';
  anchor.click();
  toast('The public interface document has been exported', 'success');
}
