        </label>
        <footer class="bbs-modal-foot">
          <button class="bbs-btn" type="button" @click="cancelEdit">Cancel</button>
          <button class="bbs-btn bbs-btn-primary" type="button" @click="saveEdit">Save </button>
        </footer>
      </div>
    </ModalMask>
  </section>
</template>

